namespace Zodiac.Framework.Formulas;

/// <summary>Checks a calculated damage envelope against signed16 storage without clamping or truncating it.</summary>
internal static class FormulaDamageBounds
{
    /// <summary>
    /// For damage calculations, this check determines whether or not the generated damage falls within
    /// the 16-bit range of numbers generated by the original FFT. So long as the minimum and maximum
    /// damage values are within the range of -32768 to 32767, and the minimum is less than or equal to
    /// the maximum, the damage values are considered valid.
    /// </summary>
    /// <param name="minimumDamage"></param>
    /// <param name="maximumDamage"></param>
    /// <returns></returns>
    public static bool FitsSigned16Range(long minimumDamage, long maximumDamage) =>
        minimumDamage >= short.MinValue && maximumDamage <= short.MaxValue && minimumDamage <= maximumDamage;
}
